import { timeZoneAt } from '@restspot/shared'
import type { ImportedListing } from './osm.ts'

const lit = (v: string | null) => (v === null ? 'null' : `'${v.replace(/'/g, "''")}'`)
const json = (v: unknown) => `${lit(JSON.stringify(v))}::jsonb`

/**
 * SQL that upserts listings by `source_ref`. Re-running an import refreshes OSM
 * fields but never touches listings users have since verified or edited.
 */
export function toSql(listings: ImportedListing[], comment: string): string {
  const lines = [
    `-- ${comment}`,
    '-- Generated by tools/osm-import. Data © OpenStreetMap contributors, ODbL 1.0.',
    '-- Run in the Supabase SQL editor (or psql) as the project owner.',
    'begin;',
    'set local search_path = public, extensions;',
    '',
    'create temporary table osm_import (',
    '  source_ref text primary key, source text, name text, lat double precision, lng double precision, time_zone text,',
    '  access_type text, fee text, key_required text, hours jsonb, notes text, rooms jsonb',
    ') on commit drop;',
    '',
  ]
  for (let i = 0; i < listings.length; i += 500) {
    const chunk = listings.slice(i, i + 500)
    lines.push('insert into osm_import values')
    lines.push(
      chunk
        .map(
          (l) =>
            `  (${lit(l.sourceRef)}, ${lit(l.source)}, ${lit(l.name)}, ${l.lat}, ${l.lng}, ${lit(timeZoneAt({ lat: l.lat, lng: l.lng }))}, ` +
            `${lit(l.accessType)}, ${lit(l.fee)}, ${lit(l.keyRequired)}, ${json(l.hours)}, ${lit(l.notes)}, ${json(l.rooms)})`,
        )
        .join(',\n') + '\non conflict (source_ref) do nothing;',
    )
    lines.push('')
  }
  lines.push(`
-- New listings.
insert into locations (name, geog, time_zone, access_type, fee, key_required, hours, notes, source, source_ref, verified)
select name, st_setsrid(st_makepoint(lng, lat), 4326)::geography, time_zone, access_type, fee, key_required, hours, notes,
       source, source_ref, false
from osm_import
on conflict (source_ref) do nothing;

-- Refresh OSM listings nobody has touched since import (only the import created them).
update locations l set
  name = i.name,
  geog = st_setsrid(st_makepoint(i.lng, i.lat), 4326)::geography,
  access_type = i.access_type,
  fee = i.fee,
  key_required = i.key_required,
  hours = i.hours,
  notes = i.notes,
  updated_at = now()
from osm_import i
where l.source_ref = i.source_ref
  and l.source in ('osm', 'poi_inferred')
  and not l.verified
  and not exists (select 1 from location_edits e where e.location_id = l.id and e.kind <> 'create');

-- Rooms for imported listings that don't have any yet.
insert into rooms (location_id, designation, layout, changing_table, ada_accessible, position)
select l.id, r.value ->> 'designation', r.value ->> 'layout', r.value ->> 'changing_table', r.value ->> 'ada_accessible', r.ordinality - 1
from osm_import i
join locations l on l.source_ref = i.source_ref
cross join lateral jsonb_array_elements(i.rooms) with ordinality r
where not exists (select 1 from rooms x where x.location_id = l.id);

-- History entry so the listing shows where it came from.
insert into location_edits (location_id, editor_id, kind, snapshot)
select l.id, null, 'create', location_json(l)
from locations l
join osm_import i on i.source_ref = l.source_ref
where not exists (select 1 from location_edits e where e.location_id = l.id);

commit;
`)
  return lines.join('\n')
}
